import{_ as a,o as s,c as n,a2 as t}from"./chunks/framework.CDpkVv68.js";const g=JSON.parse('{"title":"Spellbooks, scrolls and reagents","description":"","frontmatter":{},"headers":[],"relativePath":"guide/magic/spellbooks-scrolls-and-reagents.md","filePath":"guide/magic/spellbooks-scrolls-and-reagents.md"}'),o={name:"guide/magic/spellbooks-scrolls-and-reagents.md"};function r(l,e,i,c,d,p){return s(),n("div",null,[...e[0]||(e[0]=[t('<h1 id="spellbooks-scrolls-and-reagents" tabindex="-1">Spellbooks, scrolls and reagents <a class="header-anchor" href="#spellbooks-scrolls-and-reagents" aria-label="Permalink to &quot;Spellbooks, scrolls and reagents&quot;">​</a></h1><p><strong>Design status: Proposed.</strong> <strong>Implementation:</strong> this redesign is not established as implemented. <strong>Availability:</strong> not established as live. <strong>Verification:</strong> documentation review only. <strong>Reviewed:</strong> 2026-10-09 against Batch 04.</p><p><a href="/Syrolands-Public/game-design/magic/spellbooks-scrolls-and-reagents.html">Full design specification</a></p><p>Learned magical knowledge should stay with the character. The baseline personal book should not normally drop, but its exact replacement/protection mechanism is undecided. This is not general item insurance.</p><p>Rare physical grimoires and manuscripts are different: they can carry valuable knowledge, annotations or reference benefits and can be lootable. Better indexing might help you consult an unmemorized pattern; a rare book is not simply a flat Magery bonus.</p><p>Scrolls are physical consumables and generally drop on death. They may provide temporary access or a prepared variant, and could shorten reference for an unmemorized spell. An emergency Dispel scroll illustrates tactical value at consumable cost. Ordinary casting scrolls do not permanently teach; specially designed teaching artifacts remain an open question.</p><p>Reagents remain risky physical resources that generally drop on death. Catalysts, stabilizers and other materials may support patterns and variants, with Alchemy processing and Inscription connections. No recipe, substitution or failure-consumption rule is finalized.</p><p><a href="/Syrolands-Public/guide/professions/inscription.html">Inscription</a> · <a href="/Syrolands-Public/guide/magic/memory-and-familiarity.html">Memory</a>.</p>',8)])])}const u=a(o,[["render",r]]);export{g as __pageData,u as default};
